const menuBtn = document.getElementById('menuBtn');
const mainNav = document.getElementById('mainNav');

menuBtn.addEventListener('click', () => {
  const open = mainNav.classList.toggle('open');
  menuBtn.setAttribute('aria-expanded', String(open));
});

mainNav.querySelectorAll('a').forEach(link => {
  link.addEventListener('click', () => {
    mainNav.classList.remove('open');
    menuBtn.setAttribute('aria-expanded', 'false');
  });
});

const observer = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('show');
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.12 });

document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

const cursorGlow = document.getElementById('cursorGlow');
window.addEventListener('pointermove', e => {
  cursorGlow.style.left = `${e.clientX}px`;
  cursorGlow.style.top = `${e.clientY}px`;
});

document.getElementById('year').textContent = new Date().getFullYear();

/*
  UBAH TANGGAL MATCH DI BAWAH INI.
  Format: YYYY-MM-DDTHH:MM:SS+07:00
  Contoh: 2026-09-12T20:00:00+07:00
*/
const matchDate = new Date('2026-09-12T20:00:00+07:00');
const countdown = document.getElementById('countdown');
const matchDateLabel = document.getElementById('matchDateLabel');

if (!isNaN(matchDate)) {
  matchDateLabel.textContent = new Intl.DateTimeFormat('id-ID', {
    day:'2-digit', month:'long', year:'numeric',
    hour:'2-digit', minute:'2-digit'
  }).format(matchDate) + ' WIB';

  const tick = () => {
    const diff = matchDate - new Date();
    if (diff <= 0) {
      countdown.textContent = 'MATCH TIME';
      return;
    }
    const d = Math.floor(diff / 86400000);
    const h = Math.floor(diff / 3600000) % 24;
    const m = Math.floor(diff / 60000) % 60;
    const s = Math.floor(diff / 1000) % 60;
    countdown.textContent = `${String(d).padStart(2,'0')}D : ${String(h).padStart(2,'0')}H : ${String(m).padStart(2,'0')}M : ${String(s).padStart(2,'0')}S`;
  };
  tick();
  setInterval(tick, 1000);
}

(function createEsportsParticles(){const wrap=document.getElementById("bgParticles");if(!wrap)return;const count=window.innerWidth<700?20:42;for(let i=0;i<count;i++){const p=document.createElement("i");p.className="bg-particle"+(i%5===0?" pink":"");p.style.left=(Math.random()*100)+"%";p.style.top=(Math.random()*100)+"%";p.style.animationDuration=(8+Math.random()*12)+"s";p.style.animationDelay=(-Math.random()*16)+"s";p.style.opacity=(.15+Math.random()*.5).toFixed(2);wrap.appendChild(p)}})();
(function esportsParallax(){if(window.matchMedia("(pointer: coarse)").matches)return;const logo=document.querySelector(".hero-logo-wrap"),copy=document.querySelector(".hero-copy");window.addEventListener("pointermove",e=>{const x=e.clientX/window.innerWidth-.5,y=e.clientY/window.innerHeight-.5;if(logo)logo.style.transform=`translate3d(${x*12}px,${y*8}px,0)`;if(copy)copy.style.transform=`translate3d(${x*-5}px,${y*-3}px,0)`},{passive:true})})();

// ===== V10.8.2 EMBEDDED MUSIC - NO EXTERNAL AUDIO FILE NEEDED =====
(function serenityEmbeddedMusic(){
  const AUDIO_DATA = "data:audio/mpeg;base64,";

  let audio = document.getElementById("serenityBgMusic");
  if (!audio) {
    audio = document.createElement("audio");
    audio.id = "serenityBgMusic";
    audio.loop = true;
    audio.preload = "auto";
    document.body.appendChild(audio);
  }
  audio.src = AUDIO_DATA;
  audio.load();

  let control = document.getElementById("musicControl");
  if (!control) {
    control = document.createElement("div");
    control.id = "musicControl";
    control.className = "music-control";
    control.innerHTML = `
      <button type="button" id="musicToggle" class="music-toggle" aria-label="Toggle background music">
        <span id="musicIcon">♪</span>
        <span id="musicLabel">PLAY MUSIC</span>
      </button>
      <input id="musicVolume" class="music-volume" type="range" min="0" max="100" value="35" aria-label="Music volume">
    `;
    document.body.appendChild(control);
  }

  // Fallback styling so the control works even if CSS wasn't updated.
  if (!document.getElementById("serenityMusicFallbackStyle")) {
    const st = document.createElement("style");
    st.id = "serenityMusicFallbackStyle";
    st.textContent = `
      .music-control{position:fixed;right:18px;bottom:18px;z-index:99999;display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid #22e7f2;background:rgba(3,8,14,.92);box-shadow:0 10px 30px rgba(0,0,0,.5)}
      .music-toggle{border:0;background:transparent;color:#fff;cursor:pointer;font-weight:700;letter-spacing:1px;display:flex;align-items:center;gap:7px}
      .music-toggle #musicIcon{color:#22e7f2;font-size:18px}
      .music-toggle.is-playing #musicIcon{color:#ff2c86}
      .music-volume{width:80px;accent-color:#22e7f2}
      @media(max-width:640px){.music-control{right:10px;bottom:10px}.music-volume{width:58px}}
    `;
    document.head.appendChild(st);
  }

  const toggle = document.getElementById("musicToggle");
  const label = document.getElementById("musicLabel");
  const icon = document.getElementById("musicIcon");
  const volume = document.getElementById("musicVolume");
  const savedVolume = Number(localStorage.getItem("serenityMusicVolume") || 35);
  audio.volume = Math.max(0.05, Math.min(1, savedVolume / 100));
  if (volume) volume.value = String(savedVolume);

  function paint(message) {
    const playing = !audio.paused && !audio.ended;
    if (label) label.textContent = message || (playing ? "MUSIC OFF" : "PLAY MUSIC");
    if (icon) icon.textContent = playing ? "♫" : "♪";
    if (toggle) toggle.classList.toggle("is-playing", playing);
  }

  async function playNow() {
    try {
      audio.muted = false;
      if (audio.volume <= 0) audio.volume = 0.35;
      await audio.play();
      localStorage.setItem("serenityMusicMuted", "0");
      paint();
      return true;
    } catch (err) {
      console.error("SERENITY MUSIC ERROR", err);
      paint("CLICK AGAIN");
      return false;
    }
  }

  toggle.addEventListener("click", async (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (audio.paused) {
      await playNow();
    } else {
      audio.pause();
      localStorage.setItem("serenityMusicMuted", "1");
      paint();
    }
  });

  if (volume) {
    volume.addEventListener("input", () => {
      const v = Number(volume.value);
      audio.volume = Math.max(0, Math.min(1, v / 100));
      localStorage.setItem("serenityMusicVolume", String(v));
      paint();
    });
  }

  // Also start on first user click outside the control unless user explicitly muted.
  const firstStart = async (e) => {
    if (e.target && e.target.closest && e.target.closest("#musicControl")) return;
    if (localStorage.getItem("serenityMusicMuted") !== "1") await playNow();
    document.removeEventListener("click", firstStart);
    document.removeEventListener("touchend", firstStart);
  };
  document.addEventListener("click", firstStart);
  document.addEventListener("touchend", firstStart, {passive:true});

  audio.addEventListener("canplaythrough", () => paint());
  audio.addEventListener("play", () => paint());
  audio.addEventListener("pause", () => paint());
  audio.addEventListener("error", () => {
    console.error("Embedded audio error", audio.error);
    paint("AUDIO ERROR");
  });

  paint();
})();


// ===== V10.9.1 ANNOUNCEMENT CENTER FIX =====
document.addEventListener("DOMContentLoaded", function(){
  const KEY="serenity_announcements_v109";
  const defaults=[{
    id:"welcome-v109",title:"WELCOME TO SERENITY 155",category:"TEAM",date:"2026-08-20",
    message:"Selamat datang di official website SQUAD SERENITY 155. Pantau roster, achievement, jadwal pertandingan, match history, sponsor, dan informasi terbaru kami di sini.",
    pinned:true,active:true
  }];
  const getItems=()=>{try{const r=localStorage.getItem(KEY);return r?JSON.parse(r):defaults}catch(e){return defaults}};
  const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
  const modal=document.getElementById("announcementModal"),list=document.getElementById("announcementList");
  const navBtn=document.getElementById("announcementNavBtn"),floatBtn=document.getElementById("announcementFloatBtn");
  const closeBtn=document.getElementById("announcementCloseBtn");
  if(!modal||!list)return;
  function render(){
    const rows=getItems().filter(x=>x.active!==false).sort((a,b)=>(b.pinned===true)-(a.pinned===true)||String(b.date||"").localeCompare(String(a.date||"")));
    list.innerHTML=rows.length?rows.map(a=>`<article class="announcement-card ${a.pinned?'is-pinned':''}">
      ${a.image?`<button class="announcement-image-wrap" type="button" data-ann-image="${esc(a.id)}"><img class="announcement-image" src="${a.image}" alt="${esc(a.title||"Announcement")}"></button>`:""}
      <div class="announcement-card-body">
        <div class="announcement-meta"><span class="announcement-category">${esc(a.category||"INFO")}</span><time>${esc(a.date||"")}</time>${a.pinned?'<b>PINNED</b>':''}</div>
        <h3>${esc(a.title||"ANNOUNCEMENT")}</h3><p>${esc(a.message||"")}</p>
      </div>
    </article>`).join(""):'<div class="announcement-empty">Belum ada pengumuman aktif.</div>';
  }
  function open(){render();modal.classList.add("is-open");modal.setAttribute("aria-hidden","false");document.body.classList.add("announcement-open");localStorage.setItem("serenity_announcement_seen","1");document.querySelectorAll(".announcement-badge,#announcementFloatBadge").forEach(x=>x.style.display="none")}
  function close(){modal.classList.remove("is-open");modal.setAttribute("aria-hidden","true");document.body.classList.remove("announcement-open")}
  if(navBtn)navBtn.addEventListener("click",open);
  if(floatBtn)floatBtn.addEventListener("click",open);
  if(closeBtn)closeBtn.addEventListener("click",close);
  modal.querySelectorAll("[data-close-announcement]").forEach(x=>x.addEventListener("click",close));
  list.addEventListener("click",e=>{
    const btn=e.target.closest("[data-ann-image]");
    if(!btn)return;
    const a=getItems().find(x=>x.id===btn.dataset.annImage);
    if(!a?.image)return;
    const viewer=document.createElement("div");
    viewer.className="announcement-image-viewer";
    viewer.innerHTML=`<div class="announcement-image-viewer-backdrop"></div><div class="announcement-image-viewer-box"><button type="button" class="announcement-image-viewer-close">×</button><img src="${a.image}" alt="${esc(a.title||"Announcement")}"><h3>${esc(a.title||"ANNOUNCEMENT")}</h3></div>`;
    document.body.appendChild(viewer);
    viewer.addEventListener("click",ev=>{
      if(ev.target.classList.contains("announcement-image-viewer-backdrop")||ev.target.classList.contains("announcement-image-viewer-close"))viewer.remove();
    });
  });
  document.addEventListener("keydown",e=>{if(e.key==="Escape")close()});
  if(localStorage.getItem("serenity_announcement_seen")==="1")document.querySelectorAll(".announcement-badge,#announcementFloatBadge").forEach(x=>x.style.display="none");
});
